// Signs Android release builds with the keystore in /credentials (gitignored) instead of the
// debug key. android/ is generated by `expo prebuild`, so this is applied as a config plugin.
//
// credentials/keystore.properties:
//   storeFile=release.jks
//   storePassword=...
//   keyAlias=car-wash-staff
//   keyPassword=...
const { withAppBuildGradle } = require('expo/config-plugins');

const MARKER = '// @generated withReleaseSigning';

const RELEASE_SIGNING = `    signingConfigs {
        ${MARKER}
        release {
            def keystorePropsFile = rootProject.file('../credentials/keystore.properties')
            if (keystorePropsFile.exists()) {
                def keystoreProps = new Properties()
                keystorePropsFile.withInputStream { keystoreProps.load(it) }
                storeFile rootProject.file('../credentials/' + keystoreProps['storeFile'])
                storePassword keystoreProps['storePassword']
                keyAlias keystoreProps['keyAlias']
                keyPassword keystoreProps['keyPassword']
            }
        }`;

module.exports = function withReleaseSigning(config) {
  return withAppBuildGradle(config, (cfg) => {
    let gradle = cfg.modResults.contents;
    if (gradle.includes(MARKER)) return cfg;

    const withConfig = gradle.replace(/^    signingConfigs \{/m, RELEASE_SIGNING);
    // Only the release buildType: its signingConfig line comes after "release {" inside buildTypes.
    const withRelease = withConfig.replace(
      /(buildTypes \{[\s\S]*?release \{[\s\S]*?)signingConfig signingConfigs\.debug/,
      '$1signingConfig signingConfigs.release',
    );
    if (withConfig === gradle || withRelease === withConfig) {
      throw new Error('withReleaseSigning: app/build.gradle layout changed; update plugins/withReleaseSigning.js');
    }
    cfg.modResults.contents = withRelease;
    return cfg;
  });
};
